// ⚙️ CAMBIA ESTOS 2 DATOS
const CLAVE = 'PEGA_AQUI_TU_N8N_WEBHOOK_SECRET';      // la misma que pusiste en Render
const CORREO_ADMIN = 'consultas@solucionesintegralesjb.com'; // a dónde llegan los avisos del equipo
const WEB = 'https://sijb-bootcamp.vercel.app';

const entrada = $input.first().json;
const clave = (entrada.headers || {})['x-sijb-key'];
if (clave !== CLAVE) {
  // Rechaza avisos que no vienen de tu plataforma
  return [];
}
const e = entrada.body || {};
const d = e.datos || {};
const salida = [];
const alEquipo = (asunto, texto) => salida.push({ json: { para: CORREO_ADMIN, asunto, texto } });
const alAlumno = (correo, asunto, texto) => { if (correo) salida.push({ json: { para: correo, asunto, texto } }); };

switch (e.evento) {
  case 'reclamo.nuevo':
    alEquipo(`⚠️ Nuevo ${d.type === 'queja' ? 'queja' : 'reclamo'} ${d.code} (responder en 15 días hábiles)`,
      `Llegó una hoja al Libro de Reclamaciones.\n\nCódigo: ${d.code}\nPlazo de respuesta: ${d.deadline}\nDetalle: ${d.detail}\nPedido: ${d.request}\n\nRespóndela en: ${WEB}/admin/complaints`);
    break;
  case 'pregunta.nueva':
    alEquipo(`💬 Nueva pregunta en "${d.leccion}"`,
      `${d.alumno} preguntó en ${d.curso} › ${d.leccion}:\n\n"${d.pregunta}"\n\nResponde en: ${WEB}${d.enlaceAdmin}`);
    break;
  case 'pago.confirmado':
    alAlumno(d.email, `Tu certificado de "${d.curso}" está habilitado`,
      `Hola ${d.nombre || ''},\n\nConfirmamos tu pago. Cuando completes el curso y tus datos en «Mi perfil», descarga tu certificado oficial en:\n${WEB}/certificates/${d.courseId}\n\nSoluciones Integrales JB`);
    break;
  case 'alumno.registrado':
    alAlumno(d.email, '¡Bienvenido(a) al Bootcamp SIJB! 🎓',
      `Hola ${d.nombre || ''},\n\nGracias por unirte a SIJB Bootcamp. Confirma tu correo y empieza tu primer curso:\n${WEB}/courses\n\nSoluciones Integrales JB · Tu mejor opción tecnológica`);
    alEquipo('👤 Nuevo alumno registrado', `${d.nombre || ''} ${d.apellido || ''} (${d.email}) creó su cuenta.`);
    break;
  case 'examen_final.aprobado':
    alAlumno(d.email, `🏆 ¡Aprobaste el examen final de ${d.curso}!`,
      `¡Felicitaciones ${d.nombre || ''}! Aprobaste con ${d.nota} %.\nDescarga tu constancia aquí: ${WEB}/certificates/${d.courseId}?tipo=constancia`);
    break;
  case 'pregunta.respondida':
    alAlumno(d.email, `Respondieron tu pregunta en "${d.leccion}"`,
      `Hola ${d.alumno || ''},\n\nTu pregunta: "${d.pregunta}"\n\nRespuesta del equipo SIJB:\n${d.respuesta}\n\nVer la lección: ${WEB}/notifications`);
    break;
  case 'resena.nueva':
    alEquipo(`⭐ Nueva reseña (${d.estrellas}/5) en ${d.curso}`, `${d.alumno}: ${d.comentario || '(sin comentario)'}\n\nModera en: ${WEB}/admin/community`);
    break;
  case 'prueba':
    alEquipo('✅ Prueba de n8n', 'La conexión entre SIJB Bootcamp y n8n funciona correctamente.');
    break;
  default:
    // curso.inscripcion, curso.completado, curso.publicado: úsalos para tus propias automatizaciones
    break;
}
return salida;
